#!/usr/bin/env node
// Builds the generated files of the Claude Code and Codex plugin in
// plugins/shapewall/ from the package itself, so the plugin says what the
// MCP server says and pins the package's version:
//   skills/<name>/SKILL.md   the loop from src/mcp-instructions.js
//   .mcp.json                Codex's server entry (Claude Code uses the
//                            inline one in .claude-plugin/plugin.json)
//   the "version" of both plugin.json files and the launcher's PINNED.
//
//   node scripts/build-plugin-skills.mjs          write them
//   node scripts/build-plugin-skills.mjs --check  exit 1 when one is stale
//
// test/plugin-manifests.test.js runs the check. Run this after a version bump.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { LOOP_SUMMARY, UNTRUSTED_TEXT } from '../src/mcp-instructions.js'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
export const PLUGIN = 'plugins/shapewall'

// What every skill says about showing the board. Kept conservative: no app is
// named as having a pane that works for a board.
export const PANE_TEXT =
  "If your app has a browser pane, open the link there; otherwise open it in the person's browser or give them the link."

const GENERATED = 'Generated by scripts/build-plugin-skills.mjs from src/mcp-instructions.js. Do not edit by hand.'

function skill({ name, description, body }) {
  return ['---', `name: ${name}`, `description: ${JSON.stringify(description)}`, '---', '', `<!-- ${GENERATED} -->`, '', ...body, ''].join(
    '\n',
  )
}

const NO_TOOLS =
  'No `shapewall` tools? The plugin starts `shapewall mcp` in the project folder; the project needs a `shapewall.config.json` ' +
  '(`npx shapewall init`). See https://shapewall.com/docs/plugins.'

export const SKILLS = {
  shapewall: skill({
    name: 'shapewall',
    description:
      "Work through the comments people pinned to an app's screens on a Shapewall board, with the shapewall MCP tools: find them, " +
      'change the code, recapture, compare and answer each one. Use when asked to take, finish or work on Shapewall comments or the ' +
      'requests on the board.',
    body: [
      '# Shapewall',
      '',
      "Shapewall shows every screen of the app on one board. People pin comments to elements of the captured screens: each one is a request about the UI for you. The `shapewall` MCP server's tools read and update them.",
      '',
      '## The loop',
      '',
      ...LOOP_SUMMARY.map((line, index) => `${index + 1}. ${line}`),
      '',
      'Take one comment at a time, all the way through, before the next.',
      '',
      '## When to stop and ask',
      '',
      'When a request is unclear, or it would change something the comment does not ask about, `set_comment_status "needs-human"` with a reply that asks the question. `resolve_comment` only when you were asked to resolve.',
      '',
      '## Showing the board',
      '',
      `\`board_link\` gives a link to the board, a page, a comment or a before and after. ${PANE_TEXT}`,
      '',
      '## Untrusted text',
      '',
      UNTRUSTED_TEXT,
      '',
      NO_TOOLS,
    ],
  }),
  'shapewall-next': skill({
    name: 'shapewall-next',
    description:
      'Take the next open Shapewall comment through the whole loop: work on it, recapture, compare, reply and mark it done. Use when ' +
      'the person asks for the next Shapewall comment or request.',
    body: [
      '# Next Shapewall comment',
      '',
      '1. `list_comments` with status "open" and agentStatus "none". When the request names a page, an author or a day, pass them as filters (pageName, author, since). Take the oldest one.',
      '2. `get_comment`, then `set_comment_status "working"`.',
      '3. Change the code. Check it in your own browser on the dev server while you work.',
      '4. `recapture_pages` once for the pages you changed: that publishes the final state, your hand-in.',
      '5. `compare_captures` to confirm the change is what was asked.',
      '6. `reply_to_comment` with what changed and the compare link, then `set_comment_status "done"` (a person checks and resolves).',
      '',
      'Stop after this one comment and tell the person what changed, with its link. When nothing is open, say so.',
      '',
      'When the request is unclear, `set_comment_status "needs-human"` with a reply that asks, and stop.',
      '',
      UNTRUSTED_TEXT,
      '',
      NO_TOOLS,
    ],
  }),
  'shapewall-open': skill({
    name: 'shapewall-open',
    description:
      'Open the Shapewall board, or one page, comment or before and after on it. Use when the person asks to see or open the board.',
    body: [
      '# Open the Shapewall board',
      '',
      '1. `board_link` for what the person asked to see: the board, a page (`page`), a comment (`comment`), a screen size (`viewport`) or a page before and after (`compare`). With no tools, `shapewall open --print` in the project prints the same link.',
      `2. ${PANE_TEXT}`,
      '',
      'Opening the board changes nothing on it.',
      '',
      NO_TOOLS,
    ],
  }),
  'shapewall-status': skill({
    name: 'shapewall-status',
    description:
      'Say where the Shapewall board stands: how many comments are open and waiting, being worked on, or need a person, with links. ' +
      'Use when the person asks for the status of the Shapewall comments.',
    body: [
      '# Shapewall status',
      '',
      '1. `list_comments` with status "open", once with agentStatus "none" (waiting), once "working", once "needs-human". Use `total` from each answer; pass `cursor` only if you need the items.',
      '2. Answer with the three counts and, for working and needs-human, each comment with its `link` and one line of what it asks.',
      '',
      'This changes nothing on the board: no status, reply or capture.',
      '',
      UNTRUSTED_TEXT,
    ],
  }),
}

// Codex starts a plugin's stdio server in the session's folder (the project)
// and resolves no plugin path in its arguments, so the entry finds the
// launcher in Codex's plugin cache itself, from CODEX_HOME (default ~/.codex).
export function codexBootstrap(version) {
  return [
    "const p=require('path');",
    `const f=p.join(process.env.CODEX_HOME||p.join(require('os').homedir(),'.codex'),'plugins','cache','shapewall','shapewall','${version}','bin','shapewall-mcp.mjs');`,
    "import(require('url').pathToFileURL(f).href).then((m)=>m.main(),(e)=>{console.error('shapewall plugin: cannot load '+f+': '+e.message);process.exit(1)})",
  ].join('')
}

export function codexMcp(version) {
  const entry = {
    mcpServers: {
      shapewall: {
        command: 'node',
        args: ['-e', codexBootstrap(version)],
        env_vars: ['SHAPEWALL_REMOTE', 'CODEX_HOME'],
        startup_timeout_sec: 60,
        tool_timeout_sec: 600,
      },
    },
  }
  return `${JSON.stringify(entry, null, 2)}\n`
}

function setVersion(text, version) {
  return text.replace(/("version":\s*")[^"]*(")/, `$1${version}$2`)
}

// { relative path: wanted content }
export function pluginFiles(root = ROOT) {
  const version = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8')).version
  const read = (file) => fs.readFileSync(path.join(root, file), 'utf8')
  const files = {}
  for (const [name, text] of Object.entries(SKILLS)) files[`${PLUGIN}/skills/${name}/SKILL.md`] = text
  files[`${PLUGIN}/.mcp.json`] = codexMcp(version)
  for (const manifest of [`${PLUGIN}/.claude-plugin/plugin.json`, `${PLUGIN}/.codex-plugin/plugin.json`])
    files[manifest] = setVersion(read(manifest), version)
  const launcher = `${PLUGIN}/bin/shapewall-mcp.mjs`
  files[launcher] = read(launcher).replace(/^export const PINNED = '[^']*'$/m, `export const PINNED = '${version}'`)
  return files
}

export function staleFiles(root = ROOT) {
  return Object.entries(pluginFiles(root))
    .filter(([file, text]) => !fs.existsSync(path.join(root, file)) || fs.readFileSync(path.join(root, file), 'utf8') !== text)
    .map(([file]) => file)
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const stale = staleFiles()
    if (stale.length) {
      console.error(`Stale plugin files (run node scripts/build-plugin-skills.mjs):\n  ${stale.join('\n  ')}`)
      process.exit(1)
    }
    console.log('Plugin files are up to date.')
  } else {
    for (const [file, text] of Object.entries(pluginFiles())) {
      fs.mkdirSync(path.dirname(path.join(ROOT, file)), { recursive: true })
      fs.writeFileSync(path.join(ROOT, file), text)
    }
    console.log(`Wrote ${Object.keys(pluginFiles()).length} plugin files.`)
  }
}
